<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class SmartRegistration {
 public static function request(\PDO $p,array $d,?int $actor=null,?int $target=null):string {
  $email=Core::email($d['email']??'');$name=Core::text($d['full_name']??'');if(empty($d['organisation_id'])&&!$target){$existingOrg=Database::query($p,"SELECT s.organisation_id FROM staff_profiles s JOIN staff_registry r ON r.staff_identity_id=s.staff_identity_id LEFT JOIN users u ON u.staff_identity_id=s.staff_identity_id WHERE s.official_email=? AND r.status='PRE_VERIFIED' AND u.id IS NULL",[$email])->fetchColumn();$d['organisation_id']=$existingOrg?:Database::query($p,"SELECT setting_value FROM system_settings WHERE setting_key='registration_default_pkd'")->fetchColumn();}if(empty($d['organisation_id']))throw new \RuntimeException('Admin perlu menetapkan organisasi routing portal sebelum pendaftaran.');$org=Core::id($d['organisation_id']);$type=RegistrationMaster::emailType($p,$email);Accounts::throttle($p,'registration',$email);
  if(!Database::query($p,'SELECT 1 FROM organisations WHERE id=? AND is_active=1',[$org])->fetchColumn())throw new \InvalidArgumentException('Organisasi tidak sah.');[$prof,$position,$grade]=RegistrationMaster::employment($p,$d);$phone=RegistrationMaster::phone(Core::text($d['mobile_phone']??'',30,false));
  $lock='ep_reg_'.substr(hash('sha256',(string)$p->query('SELECT DATABASE()')->fetchColumn()),0,40);if((int)Database::query($p,'SELECT GET_LOCK(?,5)',[$lock])->fetchColumn()!==1)throw new \RuntimeException('Sila cuba kemudian.');
  try{Core::tx($p,function()use($p,$email,$name,$org,$type,$prof,$position,$grade,$phone,$actor,$target){
   if(RegistrationMaster::profileReady($p)){ $staff=$target?Database::query($p,'SELECT staff_identity_id FROM users WHERE id=?',[$target])->fetchColumn():null;if(Database::query($p,"SELECT 1 FROM staff_email_contacts WHERE email=? AND status IN ('PENDING_ADMIN_APPROVAL','APPROVED') AND (? IS NULL OR staff_identity_id<>?)",[$email,$staff,$staff])->fetchColumn())return;}
   $existing=Database::query($p,'SELECT s.staff_identity_id,s.full_name,s.organisation_id,r.status,u.id AS user_id FROM staff_profiles s LEFT JOIN staff_registry r ON r.staff_identity_id=s.staff_identity_id LEFT JOIN users u ON u.staff_identity_id=s.staff_identity_id WHERE s.official_email=? FOR UPDATE',[$email])->fetch();
   if(!$target&&$existing&&!$existing['user_id']&&$existing['status']==='PRE_VERIFIED'&&mb_strtolower($existing['full_name'])===mb_strtolower($name)&&(int)$existing['organisation_id']===$org){Accounts::issue($p,'claim',$email,(int)$existing['staff_identity_id']);return;}
   $pending=Database::query($p,"SELECT * FROM registration_requests WHERE email=? AND status IN ('PENDING_EMAIL_VERIFICATION','PENDING_VERIFICATION','REQUEST_CORRECTION','APPROVED') ORDER BY id DESC LIMIT 1 FOR UPDATE",[$email])->fetch();
   if($pending){if($pending['email_type']==='legacy'&&!$pending['email_verified_at']&&in_array($pending['status'],['PENDING_VERIFICATION','REQUEST_CORRECTION'],true)&&mb_strtolower($pending['full_name'])===mb_strtolower($name)&&(int)$pending['organisation_id']===$org){Database::query($p,"UPDATE registration_requests SET status='PENDING_EMAIL_VERIFICATION',email_type=? WHERE id=?",[$type,$pending['id']]);Accounts::issue($p,'registration_verify',$email,null,null,(int)$pending['id']);Audit::record($p,'registration.legacy_ownership_requested',null,$org,(string)$pending['id']);}return;}
   if(($existing&&($existing['user_id']||$existing['status']!=='PRE_VERIFIED'||mb_strtolower($existing['full_name'])!==mb_strtolower($name)||(int)$existing['organisation_id']!==$org))||Database::query($p,'SELECT 1 FROM users WHERE email=?',[$email])->fetchColumn()||Database::query($p,"SELECT 1 FROM registration_requests WHERE email=? AND status IN ('PENDING_EMAIL_VERIFICATION','PENDING_VERIFICATION','REQUEST_CORRECTION','APPROVED')",[$email])->fetchColumn())return;
   Database::query($p,"INSERT INTO registration_requests(full_name,email,organisation_id,profession_id,position_id,grade_id,mobile_phone,email_type,status,requested_by,target_user_id,request_kind,existing_staff_identity_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",[$name,$email,$org,$prof,$position,$grade,$phone?:null,$type,$target?'PENDING_EMAIL_VERIFICATION':'PENDING_VERIFICATION',$actor,$target,$target?'email_change':'registration',$existing?$existing['staff_identity_id']:null]);$id=(int)$p->lastInsertId();if($target)Accounts::issue($p,'registration_verify',$email,null,$target,$id);else Accounts::notifyReviewers($p,$org,$id);Audit::record($p,$target?'registration.awaiting_email':'registration.awaiting_admin',$actor,$org,(string)$id,'core',null,null,['email_type'=>$type]);
  });}finally{Database::query($p,'SELECT RELEASE_LOCK(?)',[$lock]);}return Accounts::GENERIC;
 }
 public static function verifyEmail(\PDO $p,array $token):void {
  $r=Database::query($p,'SELECT * FROM registration_requests WHERE id=? FOR UPDATE',[$token['request_id']])->fetch();if(!$r||$r['status']!=='PENDING_EMAIL_VERIFICATION'||$r['email']!==$token['email'])throw new \RuntimeException('Permohonan/pautan telah berubah.');
  Database::query($p,"UPDATE registration_requests SET email_verified_at=UTC_TIMESTAMP(),status='PENDING_VERIFICATION' WHERE id=?",[$r['id']]);Database::query($p,"INSERT INTO registration_review_history(request_id,status,reason) VALUES(?,'PENDING_VERIFICATION','Email ownership verified; admin identity review required')",[$r['id']]);Accounts::notifyReviewers($p,(int)$r['organisation_id'],(int)$r['id']);Audit::record($p,'registration.email_verified',null,(int)$r['organisation_id'],(string)$r['id']);
 }
 public static function review(\PDO $p,int $actor,int $id,string $decision,string $reason):void {
  if(!in_array($decision,['APPROVED','REJECTED','REQUEST_CORRECTION'],true))throw new \InvalidArgumentException('Keputusan tidak sah.');$reason=Core::text($reason,500);
  Core::tx($p,function()use($p,$actor,$id,$decision,$reason){$r=Database::query($p,'SELECT * FROM registration_requests WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r||!($r['status']==='PENDING_VERIFICATION'||($r['request_kind']==='registration'&&$r['status']==='PENDING_EMAIL_VERIFICATION')))throw new \RuntimeException('Permohonan tidak menunggu semakan.');$org=(int)$r['organisation_id'];Authorization::require($p,$actor,'core.registrations.review',$org);
   $u=Database::query($p,'SELECT email FROM users WHERE id=? AND is_active=1',[$actor])->fetch();if(!$u||(int)($r['requested_by']??0)===$actor||(int)($r['target_user_id']??0)===$actor||mb_strtolower($u['email'])===mb_strtolower($r['email']))throw new \RuntimeException('Self-approval ditolak.');
   // Old pending records are not treated as evidence of ownership.
   if($decision==='APPROVED'&&$r['request_kind']==='email_change'&&!$r['email_verified_at'])throw new \RuntimeException('Pengesahan e-mel diperlukan sebelum approval.');
   if($decision==='APPROVED'){
    if($r['request_kind']==='email_change'){
     $target=Database::query($p,'SELECT u.*,s.organisation_id FROM users u JOIN staff_profiles s ON s.staff_identity_id=u.staff_identity_id WHERE u.id=? AND u.is_active=1 FOR UPDATE',[$r['target_user_id']])->fetch();if(!$target||(int)$target['organisation_id']!==$org)throw new \RuntimeException('Scope/akaun telah berubah.');Authorization::require($p,$actor,'core.registrations.review',(int)$target['organisation_id']);
     if(Database::query($p,'SELECT 1 FROM users WHERE email=? AND id<>?',[$r['email'],$target['id']])->fetchColumn()||Database::query($p,'SELECT 1 FROM staff_profiles WHERE official_email=? AND staff_identity_id<>?',[$r['email'],$target['staff_identity_id']])->fetchColumn())throw new \RuntimeException('E-mel sudah digunakan.');
     if(RegistrationMaster::profileReady($p)){if(Database::query($p,"SELECT 1 FROM staff_email_contacts WHERE email=? AND staff_identity_id<>? AND status IN ('PENDING_ADMIN_APPROVAL','APPROVED')",[$r['email'],$target['staff_identity_id']])->fetchColumn())throw new \RuntimeException('E-mel dipautkan kepada identiti lain.');if($target['email_verified_at'])Database::query($p,"INSERT IGNORE INTO staff_email_contacts(staff_identity_id,email,email_type,verified_at,approved_by,status) VALUES(?,?,?,?,?,'APPROVED')",[$target['staff_identity_id'],$target['email'],RegistrationMaster::emailType($p,$target['email']),$target['email_verified_at'],$actor]);}
     Database::query($p,'UPDATE users SET email=?,email_verified_at=?,credential_revision=credential_revision+1 WHERE id=?',[$r['email'],$r['email_verified_at'],$target['id']]);Database::query($p,'UPDATE staff_profiles SET official_email=? WHERE staff_identity_id=?',[$r['email'],$target['staff_identity_id']]);Database::query($p,'INSERT INTO staff_email_history(staff_identity_id,old_email,new_email,email_type,changed_by,approved_by) VALUES(?,?,?,?,?,?)',[$target['staff_identity_id'],$target['email'],$r['email'],$r['email_type'],$r['requested_by'],$actor]);
    }else{
     if($r['existing_staff_identity_id']&&!Database::query($p,"SELECT 1 FROM staff_profiles s JOIN staff_registry r ON r.staff_identity_id=s.staff_identity_id LEFT JOIN users u ON u.staff_identity_id=s.staff_identity_id WHERE s.staff_identity_id=? AND s.official_email=? AND s.organisation_id=? AND r.status='PRE_VERIFIED' AND u.id IS NULL FOR UPDATE",[$r['existing_staff_identity_id'],$r['email'],$org])->fetchColumn())throw new \RuntimeException('Registry telah berubah.');
     RegistrationMaster::employment($p,$r);$staff=$r['existing_staff_identity_id']?(int)$r['existing_staff_identity_id']:Staff::preverify($p,$actor,['full_name'=>$r['full_name'],'official_email'=>$r['email'],'organisation_id'=>$org,'profession_id'=>$r['profession_id'],'position_id'=>$r['position_id'],'grade_id'=>$r['grade_id']],false);if($r['mobile_phone'])Database::query($p,'UPDATE staff_profiles SET phone=? WHERE staff_identity_id=?',[$r['mobile_phone'],$staff]);Accounts::issue($p,'claim',$r['email'],$staff,null,$id);
    }
   }elseif($decision==='REQUEST_CORRECTION')Accounts::issue($p,'correction',$r['email'],null,null,$id);
   else Notifications::enqueue($p,$r['email'],'system',['message'=>'Permohonan tidak diluluskan. Sila hubungi pentadbir organisasi.']);
   Database::query($p,'UPDATE registration_requests SET status=?,reviewer_id=?,reason=? WHERE id=?',[$decision,$actor,$reason,$id]);Database::query($p,'INSERT INTO registration_review_history(request_id,actor_id,status,reason) VALUES(?,?,?,?)',[$id,$actor,$decision,$reason]);Audit::record($p,'registration.'.strtolower($decision),$actor,$org,(string)$id,'core',$reason,['status'=>$r['status']],['status'=>$decision,'email_type'=>$r['email_type']]);
  });
 }
 public static function changeEmail(\PDO $p,int $actor,string $email,string $password):string {
  Accounts::throttle($p,'email_reauth','actor:'.$actor);$email=Core::email($email);$r=Database::query($p,'SELECT u.*,s.full_name,s.organisation_id,s.profession_id,s.position_id,s.grade_id FROM users u JOIN staff_profiles s ON s.staff_identity_id=u.staff_identity_id WHERE u.id=? AND u.is_active=1',[$actor])->fetch();if(!$r||!password_verify($password,$r['password_hash']))throw new \RuntimeException('Pengesahan kata laluan gagal.');if(!$r['organisation_id'])throw new \RuntimeException('Organisasi diperlukan.');$r['email']=$email;return self::request($p,$r,$actor,$actor);
 }
}
